import sys
import math

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    q = int(data[1])

    if n == 0:
        for _ in range(q):
            print(0)
        return

    arr = list(map(int, data[2:2+n]))
    queries = []
    idx = 2 + n
    for i in range(q):
        l = int(data[idx])
        r = int(data[idx + 1])
        queries.append((l, r))
        idx += 2

    for l, r in queries:
        if l > r:
            print(0)
        elif l == r:
            print(max(0, arr[l - 1]))
        else:
            range_gcd = math.gcd(abs(arr[l - 1]), abs(arr[l]))
            for i in range(l, r):
                range_gcd = math.gcd(range_gcd, abs(arr[i]))
            print(range_gcd if range_gcd != 0 else 0)

if __name__ == "__main__":
    main()
